//! Conformance: the CPU DiT against a direct f32 reference computation.
//!
//! The fixture is generated by `scripts/reference/make_fixture.py` (pure
//! stdlib, deterministic) into a temp dir; the test loads it as a real
//! safetensors checkpoint, runs the model pipeline for a 2-chunk rollout
//! (6 latent frames, 64x64), and compares the denoised latent against a
//! reference rollout written here with plain `Vec<f32>` ops — independent
//! norms, linears, RoPE, causal attention over a host-side MemRoPE cache,
//! and DMD updates. The two rollouts share only the fixture weights, the
//! timestep-mod math inputs, and the RNG stream.

use lightx2v_core::{
    backend::Backend,
    config::{DistillConfig, GenerationConfig, MemRopeConfig, TaeConfig, WanConfig},
    geometry::Geometry,
    quant::WeightQuant,
    rng::Rng,
    weights::{wan_manifest, SafetensorsDir, WeightSource},
};
use lightx2v_cpu::CpuBackend;
use lightx2v_model::{
    pipeline::{CausalPipeline, Options, Timings},
    LightDit, TaeHv,
};
use std::collections::HashMap;
use std::path::PathBuf;

fn fixture_dir() -> PathBuf {
    let dir = std::env::temp_dir().join(format!("lx2v-fixture-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let script = manifest.join("../../scripts/reference/make_fixture.py");
    let status = std::process::Command::new("python3")
        .arg(&script)
        .arg(&dir)
        .status()
        .expect("python3 must be available to generate the fixture");
    assert!(status.success(), "make_fixture.py failed");
    dir
}

#[path = "reference.rs"]
mod reference;
use reference::*;

#[test]
fn tiny_dit_matches_direct_reference() {
    let dir = fixture_dir();
    let cfg = WanConfig::tiny();
    let src = SafetensorsDir::open(&dir).unwrap();
    assert!(lightx2v_core::weights::missing(&src, &wan_manifest(&cfg)).is_empty());
    let weights = RefWeights {
        map: wan_manifest(&cfg)
            .iter()
            .map(|(n, s)| (n.clone(), src.get(n, s).unwrap()))
            .collect(),
    };

    // Model pipeline: 2 chunks x 3 latent frames, 64x64.
    let be = CpuBackend;
    let dit = LightDit::load(&be, cfg.clone(), MemRopeConfig::default_memrope(), &src).unwrap();
    let tae = TaeHv::load(&be, TaeConfig::tiny(), &src).unwrap();
    let pipe = CausalPipeline::new(dit, tae, DistillConfig::dmd2());
    let gen = GenerationConfig {
        latent_frames: 6,
        ..GenerationConfig::short_clip()
    };
    let geometry = Geometry {
        frames: 21,
        height: 64,
        width: 64,
    };
    let embeds = vec![0.0f32; cfg.text_len * cfg.text_dim];
    let mut timings = Timings::default();
    let latent = pipe
        .denoise(
            &be,
            &embeds,
            &gen,
            &Options {
                geometry,
                seed: 0,
                ffn_chunk: usize::MAX,
            },
            &mut timings,
        )
        .unwrap();
    std::fs::remove_dir_all(&dir).ok();

    // Reference rollout with the same RNG stream and schedule.
    let schedule = lightx2v_core::schedule::DmdSchedule::dmd2();
    let text_kv = ref_text_kv(&cfg, &weights, &embeds);
    let mut caches: Vec<RefCache> = (0..cfg.layers).map(|_| RefCache::new()).collect();
    let mut rng = Rng::new(0);
    let chunk_len = cfg.in_channels * 3 * 8 * 8;
    let mut ref_latent = vec![0.0f32; chunk_len * 2];
    for ci in 0..2 {
        let mut x = rng.normal(chunk_len);
        for (i, &ts) in schedule.timesteps.iter().enumerate() {
            let (mods, head) = ref_mods(&cfg, &weights, ts as f32);
            let v = ref_chunk(
                &cfg,
                &weights,
                &x,
                &mods,
                &head,
                &text_kv,
                &mut caches,
                ci * 3,
            );
            let (st, next) = schedule.coeffs(i);
            if let Some(sn) = next {
                let noise = rng.normal(chunk_len);
                for j in 0..chunk_len {
                    x[j] = (1.0 - sn) * (x[j] - st * v[j]) + sn * noise[j];
                }
            } else {
                for j in 0..chunk_len {
                    x[j] = x[j] - st * v[j];
                }
            }
        }
        ref_latent[ci * chunk_len..(ci + 1) * chunk_len].copy_from_slice(&x);
    }

    // The two rollouts sum in different orders, so f32 rounding differs:
    // judge on max absolute error (7e-7 here), not on a relative error
    // that blows up on near-zero elements.
    let max_abs = latent
        .iter()
        .zip(&ref_latent)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    let rel = lightx2v_model::check::rel(&latent, &ref_latent);
    assert!(
        max_abs < 1e-5,
        "model vs direct reference max abs {max_abs:.3e} (rel {rel:.3e})"
    );
}

#[test]
fn cpu_kv_cache_memrope_bounds_and_keeps_sinks() {
    let be = CpuBackend;
    let cfg = MemRopeConfig::default_memrope();
    let (heads, hd, frame_tokens) = (2usize, 4, 2);
    let mut cache = be.kv_cache_new(heads, hd, cfg.cache_frames * frame_tokens);
    let mut rng = Rng::new(21);
    for frame in 0..40 {
        let rows = frame_tokens;
        let k = be.upload(&rng.normal(heads * rows * hd));
        let v = be.upload(&rng.normal(heads * rows * hd));
        let temporal: Vec<usize> = (0..rows).map(|_| frame).collect();
        be.kv_cache_append(&mut cache, &k, &v, rows, &temporal);
        be.kv_cache_memrope_update(&mut cache, &cfg, frame_tokens);
        assert!(
            be.kv_cache_len(&cache) <= cfg.cache_frames * frame_tokens,
            "frame {frame}: len {}",
            be.kv_cache_len(&cache)
        );
    }
    let temporal = be.kv_cache_temporal(&cache);
    // Sinks (frames 0,1,2) are the first rows, pinned forever.
    assert_eq!(&temporal[..frame_tokens * 3], &[0, 0, 1, 1, 2, 2]);
    // The newest frame is present.
    assert_eq!(*temporal.last().unwrap(), 39);
    // Every frame repeats its temporal index across its rows, so count
    // distinct frame indices instead: 12 frames in the cache, but the two
    // EMA slots share the first non-sink frame's index, so 11 distinct.
    let distinct: std::collections::HashSet<usize> = temporal.iter().copied().collect();
    assert_eq!(temporal.len() / frame_tokens, 12, "{temporal:?}");
    assert_eq!(distinct.len(), 11, "{temporal:?}");
    assert!(distinct.contains(&0) && distinct.contains(&39));
    // The cache still holds K/V of the right shape.
    let (k, v) = be.kv_cache_kv(&cache);
    assert_eq!(be.buf_len(&k), heads * be.kv_cache_len(&cache) * hd);
    assert_eq!(be.buf_len(&v), heads * be.kv_cache_len(&cache) * hd);
}

#[test]
fn taehv_decode_shape_deterministic_and_chunk_invariant() {
    // Tiny TAEHV: 4 latent channels, 8x8 latent spatial -> 64x64 video.
    let dir = fixture_dir();
    let be = CpuBackend;
    let src = SafetensorsDir::open(&dir).unwrap();
    let tae = TaeHv::load(&be, TaeConfig::tiny(), &src).unwrap();

    // 3 latent frames -> 9 video frames at 64x64.
    let mut rng = Rng::new(7);
    let latent = rng.normal(4 * 3 * 8 * 8);
    let video = tae.decode(&be, &latent, 3, 64, 64).unwrap();
    assert_eq!(video.frames, 9, "3 latent frames -> 4*3-3 video frames");
    assert_eq!((video.width, video.height), (64, 64));
    assert_eq!(video.rgb.len(), 9 * 64 * 64 * 3);
    // Deterministic: decoding the same latent twice gives identical bytes.
    let again = tae.decode(&be, &latent, 3, 64, 64).unwrap();
    assert_eq!(video.rgb, again.rgb);
    // Non-degenerate: the synthetic weights produce varied output, not a
    // flat field.
    let distinct: std::collections::HashSet<u8> = video.rgb.iter().copied().collect();
    assert!(
        distinct.len() > 10,
        "only {} distinct byte values",
        distinct.len()
    );
    let mean = video.rgb.iter().map(|&b| b as f64).sum::<f64>() / video.rgb.len() as f64;
    assert!((1.0..254.0).contains(&mean), "mean byte {mean:.1}");

    // Chunk invariance: 6 latent frames decoded as one 6-frame chunk must
    // equal the same latent decoded as 4+2 chunks (the MemBlock memory
    // carried across the boundary is the reference's sequential memory).
    // decode_chunk takes frame-major [frames, C, h, w]; transpose first.
    let latent6 = rng.normal(4 * 6 * 8 * 8);
    let mut z6 = vec![0.0f32; 6 * 4 * 8 * 8];
    for fi in 0..6 {
        for c in 0..4 {
            for y in 0..8 {
                for x in 0..8 {
                    z6[((fi * 4 + c) * 8 + y) * 8 + x] = latent6[((c * 6 + fi) * 8 + y) * 8 + x];
                }
            }
        }
    }
    let mut st = tae.state();
    let one = tae.decode_chunk(&be, &mut st, &z6, 6, 8, 8);
    assert_eq!(one.frames, 21, "6 latent frames -> 4*6-3 video frames");
    assert_eq!((one.width, one.height), (64, 64));
    let mut st2 = tae.state();
    let first = tae.decode_chunk(&be, &mut st2, &z6[..4 * 4 * 8 * 8], 4, 8, 8);
    let second = tae.decode_chunk(&be, &mut st2, &z6[4 * 4 * 8 * 8..], 2, 8, 8);
    assert_eq!(first.frames + second.frames, 21);
    let mut split = first.data.clone();
    split.extend_from_slice(&second.data);
    assert_eq!(one.data.len(), split.len());
    let max_abs = one
        .data
        .iter()
        .zip(&split)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    assert!(
        max_abs == 0.0,
        "chunked decode differs from single-chunk decode by {max_abs:.3e}"
    );
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn quantize_flag_parses() {
    assert_eq!("fp8".parse::<WeightQuant>(), Ok(WeightQuant::Fp8));
}
